<script setup lang="ts">
import { tx } from '@/i18n'
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import auth from '@/plugins/auth'
import NxrPageHeader from '@/components/NxrWorkspace/PageHeader.vue'
import EnterpriseCreditFinance from '@/components/EnterpriseCredit/FinancePanel.vue'
import { getPartner,listPartners,provisionPartner,setPartnerOperatorState,updatePartner,type PartnerDetail,type PartnerOperator,type PartnerPage,type PartnerProfileInput,type PartnerSummary } from '@/api/nxr/partners'
import { agentDateLabel,agentStatusLabel,formatMoney } from '../agent-workbench/lib/agentWorkbench'
defineOptions({name:'NxrPartners'})
const router=useRouter()
const canManage=auth.hasPermiAnd(['nxr:partner:manage','nxr:customer:manage'])
const canOpen=canManage&&auth.hasPermi('system:user:add')
const canFinance=auth.hasPermi('nxr:customer:finance')
const canRecharge=canFinance&&auth.hasPermi('nxr:partner:manage')
const canWorkbench=auth.hasPermiOr(['nxr:agent:workbench','nxr:agent:manage'])
const canNxrOrders=auth.hasPermi('nxr:order:list')
const canManageOperators=auth.hasPermi('nxr:agent:manage')
const emptyPage=<T,>():PartnerPage<T>=>({items:[],page:1,pageSize:20,total:0})
const listing=ref(emptyPage<PartnerSummary>()),loading=ref(false),busy=ref(false),error=ref(''),success=ref('')
const query=reactive({query:'',active:'' as boolean|'',currencyCode:'PTS'})
const detail=ref<PartnerDetail|null>(null),detailOpen=ref(false),detailLoading=ref(false),detailTab=ref('overview'),editingProfile=ref(false)
const profile=ref<PartnerProfileInput>({displayName:'',email:'',mobile:'',companyName:'',contactName:'',active:true})
const accountOpen=ref(false),accountPartner=ref<PartnerSummary|null>(null)
const blankAccount=()=>({companyName:'',contactName:'',displayName:'',email:'',mobile:'',userName:'',nickName:'',password:''})
const account=ref(blankAccount())
const financeVisible=computed(()=>Boolean(canFinance&&detail.value?.financeVisible))
const attempts=new Map<string,{fingerprint:string;key:string}>()
let listGeneration=0,detailGeneration=0,active=true
function message(e:unknown){return e instanceof Error?e.message:tx('The operation could not be completed. Please try again.')}
function profileFor(row:PartnerSummary):PartnerProfileInput{return {displayName:row.displayName,email:row.email,mobile:row.mobile||'',companyName:row.companyName,contactName:row.contactName,active:row.active}}
async function load(page=1){const current=++listGeneration;loading.value=true;error.value='';try{const value=await listPartners({page,pageSize:20,...query,active:query.active===''?undefined:query.active});if(active&&current===listGeneration)listing.value=value}catch(e){if(active&&current===listGeneration)error.value=message(e)}finally{if(active&&current===listGeneration)loading.value=false}}
async function openPartner(id:number){
  if(busy.value)return
  const current=++detailGeneration;detail.value=null;detailOpen.value=true;detailLoading.value=true;detailTab.value='overview';editingProfile.value=false;error.value='';success.value=''
  try{const value=await getPartner(id);if(active&&current===detailGeneration){detail.value=value;profile.value=profileFor(value.partner)}}
  catch(e){if(active&&current===detailGeneration)error.value=message(e)}finally{if(active&&current===detailGeneration)detailLoading.value=false}
}
async function refreshDetail(){const id=detail.value?.partner.id,current=detailGeneration;if(!id)return;try{const value=await getPartner(id);if(active&&current===detailGeneration)detail.value=value}catch(e){if(active&&current===detailGeneration)error.value=message(e)}}
async function mutate<T>(name:string,payload:object,action:(key:string)=>Promise<T>,apply:(value:T)=>void,notice:string){
  if(busy.value||!active)return false
  const fingerprint=JSON.stringify(payload);let attempt=attempts.get(name)
  if(!attempt||attempt.fingerprint!==fingerprint){attempt={fingerprint,key:crypto.randomUUID()};attempts.set(name,attempt)}
  busy.value=true;error.value='';success.value=''
  try{const value=await action(attempt.key);if(!active)return false;attempts.delete(name);apply(value);success.value=notice;return true}catch(e){if(active)error.value=message(e);return false}finally{if(active)busy.value=false}
}
function openAccount(row?:PartnerSummary){accountPartner.value=row||null;account.value=blankAccount();accountOpen.value=true;error.value='';success.value=''}
function closeAccount(){account.value.password='';attempts.delete('partner:provision');accountOpen.value=false;accountPartner.value=null}
async function saveAccount(){
  const existing=accountPartner.value
  const payload=existing?{existingCustomerId:existing.id,userName:account.value.userName.trim(),nickName:account.value.nickName.trim(),password:account.value.password}:{...account.value,displayName:account.value.companyName.trim(),nickName:account.value.nickName.trim()||account.value.contactName.trim()}
  let createdId=0
  if(await mutate('partner:provision',payload,key=>provisionPartner({...payload,requestKey:key}),value=>{createdId=value.customerId;closeAccount()},existing?tx('Partner admin account created.'):tx('Partner created.'))){await load();await openPartner(createdId);success.value=existing?tx('Partner admin account created.'):tx('Partner created.')}
}
async function saveProfile(){const id=detail.value?.partner.id;if(!id)return;const payload={...profile.value};if(await mutate(`partner:${id}:profile`,payload,()=>updatePartner(id,payload),value=>{if(detail.value)detail.value.partner=value;editingProfile.value=false},tx('Partner profile saved.')))await load(listing.value.page)}
async function toggleOperator(operator:PartnerOperator){const id=detail.value?.partner.id;if(!id)return;const payload={sysUserId:operator.sysUserId,active:!operator.active};if(await mutate(`partner:${id}:operator:${operator.sysUserId}`,payload,()=>setPartnerOperatorState(id,operator.sysUserId,payload.active),()=>{},payload.active?tx('Submission access enabled. Please sign in again.'):tx('Submission access disabled.'))){await refreshDetail();await load(listing.value.page)}}
function workspace(row:PartnerSummary,tab='clients'){void router.push({path:'/nxr/submission-workbench',query:{company:String(row.id),tab}})}
onMounted(()=>load())
onBeforeUnmount(()=>{active=false;listGeneration++;detailGeneration++;account.value.password='';attempts.clear()})
</script>

<template>
  <main class="nxr-workspace partners-page" data-testid="partner-management">
    <NxrPageHeader :title="$t('nav.partnerManagement')" :summary="$tx('{count} partners', { count: listing.total })"><template #actions><el-button :loading="loading" :disabled="busy" @click="load(listing.page)">{{ $tx('Refresh') }}</el-button><el-button v-if="canOpen" type="primary" :disabled="busy" data-testid="partner-open-create" @click="openAccount()">{{ $tx('Create Partner') }}</el-button></template></NxrPageHeader>
    <el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><el-alert v-if="success" :title="success" type="success" :closable="false" class="partner-alert" />
    <el-card shadow="never"><el-form inline @submit.prevent="load()"><el-form-item :label="$tx('Find a partner')"><el-input v-model="query.query" clearable :placeholder="$tx('Company, contact, or account')" data-testid="partner-search" /></el-form-item><el-form-item :label="$tx('Status')"><el-select v-model="query.active" style="width:120px"><el-option :label="$tx('All')" value="" /><el-option :label="$tx('Enabled')" :value="true" /><el-option :label="$tx('Disabled')" :value="false" /></el-select></el-form-item><el-form-item><el-button type="primary" native-type="submit" :loading="loading">{{ $tx('Search') }}</el-button></el-form-item></el-form>
      <el-table v-loading="loading" :data="listing.items" row-key="id" border><el-table-column :label="$tx('Partner company')" min-width="210"><template #default="{row}"><el-button link type="primary" :disabled="busy" :data-testid="`partner-detail-${row.id}`" @click="openPartner(row.id)">{{row.companyName||row.displayName}}</el-button></template></el-table-column><el-table-column :label="$tx('Contact')" min-width="140"><template #default="{row}">{{row.contactName}}<small>{{row.mobile||'—'}}</small></template></el-table-column><el-table-column :label="$tx('Admin accounts')" min-width="105"><template #default="{row}">{{ $tx('{active} / {total} enabled', { active: row.activeOperatorCount, total: row.operatorCount }) }}<small>{{row.operatorAccounts||$tx('No admin accounts')}}</small></template></el-table-column><el-table-column prop="clientCount" :label="$tx('End customers')" width="95" /><el-table-column prop="inventoryCount" :label="$tx('Cards in inventory')" width="95" /><el-table-column prop="pendingBatchCount" :label="$tx('Active batches')" width="110" /><el-table-column v-if="canFinance" :label="$tx('Enterprise credits')" min-width="145"><template #default="{row}">{{row.financeVisible&&row.walletBalance!==null?formatMoney(row.walletBalance,row.currencyCode):'—'}}</template></el-table-column><el-table-column v-if="canFinance" :label="$tx('Pending verification')" width="130"><template #default="{row}">{{row.pendingRechargeCount??'—'}}</template></el-table-column><el-table-column :label="$tx('Status')" width="85"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?$tx('Enabled'):$tx('Disabled')}}</el-tag></template></el-table-column><el-table-column :label="$tx('Actions')" min-width="165" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="openPartner(row.id)">{{ $tx('Manage') }}</el-button><el-button v-if="canWorkbench&&row.active" link type="primary" :disabled="busy" @click="workspace(row)">{{ $tx('Submission Workspace') }}</el-button></template></el-table-column></el-table><el-pagination v-if="listing.total>listing.pageSize" class="partner-pagination" layout="prev,pager,next,total" :total="listing.total" :page-size="listing.pageSize" :current-page="listing.page" :disabled="loading||busy" @current-change="load" />
    </el-card>
    <el-drawer v-model="detailOpen" :title="detail?.partner.companyName||$tx('Partner details')" size="min(1120px,96vw)" :close-on-click-modal="!busy" :show-close="!busy" destroy-on-close>
      <div v-loading="detailLoading" data-testid="partner-detail"><el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><el-alert v-if="success" :title="success" type="success" :closable="false" class="partner-alert" /><template v-if="detail"><div class="partner-detail-heading"><div><el-tag :type="detail.partner.active?'success':'info'">{{detail.partner.active?$tx('Enabled'):$tx('Disabled')}}</el-tag><span>{{detail.partner.contactName}} · {{detail.partner.mobile||'—'}}</span></div><el-button v-if="canWorkbench&&detail.partner.active" type="primary" :disabled="busy" @click="workspace(detail.partner)">{{ $tx('Open Submission Workspace') }}</el-button></div><div class="partner-stats"><article><strong>{{detail.partner.clientCount}}</strong><span>{{ $tx('End customers') }}</span></article><article><strong>{{detail.partner.inventoryCount}}</strong><span>{{ $tx('Cards in inventory') }}</span></article><article><strong>{{detail.partner.pendingBatchCount}}</strong><span>{{ $tx('Active batches') }}</span></article><article><strong>{{detail.partner.activeOperatorCount}}</strong><span>{{ $tx('Active admin accounts') }}</span></article></div>
        <el-tabs v-model="detailTab"><el-tab-pane :label="$tx('Company profile and accounts')" name="overview"><div class="partner-section-heading"><h3>{{ $tx('Partner profile') }}</h3><el-button v-if="canManage&&!editingProfile" :disabled="busy" @click="profile=profileFor(detail.partner);editingProfile=true">{{ $tx('Edit profile / status') }}</el-button></div><el-form v-if="editingProfile" label-position="top" :disabled="busy" @submit.prevent="saveProfile"><div class="partner-form-grid"><el-form-item :label="$tx('Partner company name')"><el-input v-model="profile.companyName" required maxlength="191" /></el-form-item><el-form-item :label="$tx('Account display name')"><el-input v-model="profile.displayName" required maxlength="128" /></el-form-item><el-form-item :label="$tx('Contact')"><el-input v-model="profile.contactName" required maxlength="128" /></el-form-item><el-form-item :label="$tx('Phone number')"><el-input v-model="profile.mobile" maxlength="64" /></el-form-item><el-form-item :label="$tx('Contact email')"><el-input v-model="profile.email" type="email" required maxlength="191" /></el-form-item><el-form-item :label="$tx('Status')"><el-switch v-model="profile.active" :active-text="$tx('Enabled')" :inactive-text="$tx('Disabled')" /></el-form-item></div><el-alert v-if="!profile.active" :title="$tx('Disabling this partner prevents its admin accounts from managing company activity. Historical records are retained.')" type="warning" :closable="false" /><div class="partner-actions"><el-button @click="editingProfile=false">{{ $tx('Cancel') }}</el-button><el-button type="primary" native-type="submit" :loading="busy">{{ $tx('Save profile') }}</el-button></div></el-form><el-descriptions v-else :column="2" border><el-descriptions-item :label="$tx('Company name')">{{detail.partner.companyName}}</el-descriptions-item><el-descriptions-item :label="$tx('Account name')">{{detail.partner.displayName}}</el-descriptions-item><el-descriptions-item :label="$tx('Contact')">{{detail.partner.contactName}}</el-descriptions-item><el-descriptions-item :label="$tx('Phone number')">{{detail.partner.mobile||'—'}}</el-descriptions-item><el-descriptions-item :label="$tx('Created at')">{{agentDateLabel(detail.partner.createdAt)}}</el-descriptions-item></el-descriptions><div class="partner-section-heading"><h3>{{ $tx('Admin accounts') }}</h3><el-button v-if="canOpen&&detail.partner.active" :disabled="busy" @click="openAccount(detail.partner)">{{ $tx('Add admin account') }}</el-button></div><el-table :data="detail.operators" border><el-table-column prop="userName" :label="$tx('Username')" /><el-table-column prop="nickName" :label="$tx('Name')" /><el-table-column :label="$tx('Submission access')"><template #default="{row}">{{!row.backendActive?$tx('Admin account disabled'):row.active?$tx('Enabled'):$tx('Disabled')}}</template></el-table-column><el-table-column v-if="canManageOperators" :label="$tx('Actions')" min-width="150"><template #default="{row}"><el-button link :type="row.active?'danger':'primary'" :disabled="busy||(!row.active&&!row.backendActive)" @click="toggleOperator(row)">{{row.active?$tx('Disable submission access'):$tx('Enable submission access')}}</el-button></template></el-table-column></el-table></el-tab-pane>
          <el-tab-pane v-if="financeVisible" :label="$tx('Enterprise credits')" name="wallet" lazy><EnterpriseCreditFinance :key="detail.partner.id" :company-id="detail.partner.id" :can-recharge="canRecharge&&detail.partner.active" @changed="refreshDetail();load(listing.page)"/></el-tab-pane>
          <el-tab-pane :label="$tx('Intake and submission batches')" name="batches"><div class="partner-actions"><el-button v-if="canWorkbench&&detail.partner.active" :disabled="busy" @click="workspace(detail.partner,'intakes')">{{ $tx('View customer intake and inventory') }}</el-button><el-button v-if="canWorkbench&&detail.partner.active" :disabled="busy" @click="workspace(detail.partner,'batches')">{{ $tx('View all submission batches') }}</el-button></div><h3>{{ $tx('Recent submission batches') }}</h3><el-table :data="detail.batches.items" border><el-table-column prop="batchNo" :label="$tx('Batch number')" min-width="210" /><el-table-column prop="batchName" :label="$tx('Batch name')" min-width="150" /><el-table-column :label="$tx('Status')" min-width="120"><template #default="{row}">{{agentStatusLabel(row.statusCode)}}</template></el-table-column><el-table-column prop="acceptedRows" :label="$tx('Customer orders')" width="100" /><el-table-column :label="$tx('Time')" min-width="170"><template #default="{row}">{{agentDateLabel(row.createdAt)}}</template></el-table-column><el-table-column :label="$tx('NXR actions')" min-width="180"><template #default="{row}"><el-button v-if="canNxrOrders" link type="primary" :disabled="busy" @click="router.push({path:'/nxr/orders',query:{batchId:String(row.id)}})">{{ $tx('Receive master parcel / view tracking') }}</el-button></template></el-table-column></el-table></el-tab-pane>
        </el-tabs>
      </template></div>
    </el-drawer>
    <el-dialog v-model="accountOpen" :title="accountPartner?$tx('Add partner admin account'):$tx('Create Partner')" width="min(740px,94vw)" :close-on-click-modal="false" :show-close="!busy" @closed="account.password=''" append-to-body><el-alert v-if="error" :title="error" type="error" :closable="false" class="partner-alert" /><p v-if="accountPartner">{{ $tx('Partner: ') }}{{accountPartner.companyName}}</p><el-form label-position="top" :disabled="busy" @submit.prevent="saveAccount"><div v-if="!accountPartner" class="partner-form-grid"><el-form-item :label="$tx('Partner company name')" required><el-input v-model="account.companyName" required maxlength="191" data-testid="partner-company-name" /></el-form-item><el-form-item :label="$tx('Contact')" required><el-input v-model="account.contactName" required maxlength="128" /></el-form-item><el-form-item :label="$tx('Contact email')" required><el-input v-model="account.email" type="email" required maxlength="191" /></el-form-item><el-form-item :label="$tx('Phone number')"><el-input v-model="account.mobile" maxlength="64" /></el-form-item></div><el-divider>{{ $tx('Admin sign-in account') }}</el-divider><div class="partner-form-grid"><el-form-item :label="$tx('Username')" required><el-input v-model="account.userName" required maxlength="30" autocomplete="off" data-testid="partner-user-name" /></el-form-item><el-form-item :label="$tx('Account name')"><el-input v-model="account.nickName" maxlength="30" /></el-form-item><el-form-item :label="$tx('Initial password (5–20 characters)')" required><el-input v-model="account.password" type="password" required minlength="5" maxlength="20" autocomplete="new-password" data-testid="partner-initial-password" /></el-form-item></div><div class="partner-actions"><el-button :disabled="busy" @click="closeAccount">{{ $tx('Cancel') }}</el-button><el-button type="primary" native-type="submit" :loading="busy" data-testid="partner-save-provision">{{accountPartner?$tx('Create admin account'):$tx('Confirm partner creation')}}</el-button></div></el-form></el-dialog>
</main>
</template>
<style scoped>
.partners-page{overflow-x:hidden}.partner-alert{margin-bottom:16px}.partners-page small{display:block;margin-top:5px;color:var(--el-text-color-secondary);font-size:12px;overflow-wrap:anywhere}.partner-pagination{margin-top:18px}.partner-detail-heading,.partner-section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:16px 0}.partner-detail-heading>div{display:flex;gap:12px;align-items:center}.partner-section-heading h3{margin:0;font-size:17px}.partner-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:22px 0}.partner-stats article,.partner-wallets article{padding:18px;border:1px solid var(--el-border-color);border-radius:7px}.partner-stats strong,.partner-stats span,.partner-wallets strong,.partner-wallets span{display:block}.partner-stats strong{font-size:25px;margin-bottom:8px}.partner-stats span,.partner-wallets span{font-size:12px;color:var(--el-text-color-secondary)}.partner-wallets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:20px}.partner-wallets strong{font-size:20px;margin-top:9px}.partner-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}.partner-actions{display:flex;gap:12px;justify-content:flex-end;margin:20px 0}.partner-actions .el-button{margin-left:0}.partners-page :deep(.el-dialog .el-form-item){margin-top:14px}.partners-page :deep(.el-tabs__content){overflow:visible}@media(max-width:760px){.partner-stats,.partner-wallets{grid-template-columns:repeat(2,minmax(0,1fr))}.partner-form-grid{grid-template-columns:1fr}.partner-detail-heading,.partner-section-heading{align-items:flex-start;flex-wrap:wrap}.partner-actions{flex-wrap:wrap}}
</style>
